                    </td>
                    <td
                      className={`${numberCell} border-l border-slate-200 dark:border-slate-700 ${row.newLine !== null ? 'bg-green-50 dark:bg-green-950/40' : ''}`}
                    >
                      {row.newNo}
                    </td>
                    <td className={`${textCell}${dimNew} ${newBg}`}>
                      {row.newLine === null
                        ? ' '
                        : paired
                          ? renderWords(row.oldLine ?? '', row.newLine, 'new')
                          : row.newLine || ' '}
                    </td>
                  </tr>
                )
              }
            }
          })}
