        history: [
          { instruction: 'Formal', proposal: 'x' },
          { instruction: 'Add a summary', proposal: 'y' },
        ],
      }),
      'a\n',
    )
    expect(ai.label).toBe('Formal → Add a summary → Shorter')
  })
})
