  resolved: ResolvedSuggestion,
  latestContent: string | null,
): VersionInput[] {
  const entries: VersionInput[] = []
  if (resolved.contentBefore !== latestContent) {
    entries.push({ source: 'manual', label: 'Manual edits', content: resolved.contentBefore })
  }
