      for (const entry of versionsForResolution(resolved, latestContent)) record(entry)
    },
    [latestContent, record],
  )

  return (
    <SuggestionProvider onResolved={handleResolved} onStart={onStart}>
      {children}
    </SuggestionProvider>
  )
}
