import type { Version, VersionSource } from './types'

type VersionTimelineProps = {
  versions: Version[]
  selectedId: string | null
  onSelect(id: string): void
  getModelLabel?(id: string): string
  now?: number
}

const SOURCE_LABEL: Record<VersionSource, string> = {
  initial: 'Initial',
  manual: 'Manual',
  ai: 'AI',
  restore: 'Restore',
}

