            <Command.Item
              key={preset.id}
              value={preset.label}
              keywords={[preset.slash]}
              disabled={!canRun}
              onSelect={() => run(() => runPreset(preset))}
              className={itemClass}
            >
              <span>{preset.label}</span>
              <span className="text-xs text-zinc-400">/{preset.slash}</span>
            </Command.Item>
          ))}
        </Command.Group>

        <Command.Group heading="View" className={groupClass}>
          {TABS.map((tab) => (
