              <Command.Item
                key={model.id}
                value={`Use ${model.label}`}
                keywords={['model', model.id]}
                onSelect={() => run(() => setSelectedModel(model.id))}
                className={itemClass}
              >
                <span>Use {model.label}</span>
                {model.id === selectedModel && <span aria-hidden="true">✓</span>}
