        </span>
        <span>
          <kbd>↵</kbd> run
        </span>
        <span>
          <kbd>Esc</kbd> close
        </span>
        <span>
          Type <kbd>/</kbd> in the editor for slash commands
        </span>
      </footer>
    </Command.Dialog>
  )
}
