async (page) => {
  await page.context().addInitScript(() => {
    if (!sessionStorage.getItem('seeded')) {
      localStorage.clear();
      localStorage.setItem('ai-docs:document', JSON.stringify({ content: '# Notes\n\nFirst paragraph is here.\n\nSecond paragraph goes here.\n', updatedAt: 0 }));
      sessionStorage.setItem('seeded', '1');
    }
  });
  const bodies = [];
  await page.route('**/api/suggestions', async (route) => {
    const body = JSON.parse(route.request().postData());
    bodies.push(body);
    await route.fulfill({ status: 200, headers: { 'content-type': 'text/event-stream' },
      body: `event: delta\ndata: ${JSON.stringify({ text: 'Rewritten.' })}\n\nevent: done\ndata: {"stop_reason":"end_turn"}\n\n` });
  });
  await page.goto('http://localhost:5173');
  await page.getByRole('option', { name: 'Claude Sonnet 5.5' }).waitFor({ state: 'attached' });
  const out = {};
  const palette = () => page.getByPlaceholder('Type a command or search…');

  // 11a. Palette opens from each tab
  out.paletteFromTabs = [];
  for (const tab of ['Preview', /AI Review/, 'Editor']) {
    await page.getByRole('tab', { name: tab }).click();
    await page.keyboard.press('ControlOrMeta+k');
    out.paletteFromTabs.push(await palette().isVisible());
    await page.keyboard.press('Escape');
    await palette().waitFor({ state: 'detached' });
  }

  // 11b. "Make more concise" with the cursor inside the second paragraph
  await page.getByText('Second paragraph goes here.').click();
  await page.keyboard.press('ControlOrMeta+k');
  await palette().fill('concise');
  await page.keyboard.press('Enter');
  await page.getByRole('button', { name: 'Discard' }).click();
  out.conciseSelection = bodies.at(-1)?.selection;

  // 12. Ask AI… from Preview focuses the instruction input
  await page.getByRole('tab', { name: 'Preview' }).click();
  await page.keyboard.press('ControlOrMeta+k');
  await palette().fill('ask');
  await page.keyboard.press('Enter');
  await page.waitForTimeout(100);
  out.askFocused = await page.evaluate(() => document.activeElement?.getAttribute('aria-label'));
  out.editorTabSelected = await page.getByRole('tab', { name: 'Editor' }).getAttribute('aria-selected');

  // 14. Slash menu at the start of a new line after the first paragraph
  await page.getByText('First paragraph is here.').click();
  await page.keyboard.press('End');
  await page.keyboard.type(' /');
  const menu = page.locator('.cm-tooltip-autocomplete');
  await menu.waitFor();
  out.slashOptions = (await menu.locator('li').allInnerTexts()).slice(0, 4).map((t) => t.replace(/\s+/g, ' ').trim());
  await page.keyboard.type('fix');
  await page.keyboard.press('Enter');
  await page.getByRole('button', { name: /Discard|Dismiss/ }).first().click();
  const fixBody = bodies.at(-1);
  out.fixTarget = fixBody?.selection && fixBody.document.slice(fixBody.selection.start, fixBody.selection.end);
  out.fixDocHasSlash = fixBody?.document.includes('/fix');

  // 14b. and/or does not open the menu
  await page.getByRole('tab', { name: 'Editor' }).click();
  await page.getByText('Second paragraph goes here.').click();
  await page.keyboard.press('End');
  await page.keyboard.type(' and/or');
  await page.waitForTimeout(300);
  out.andOrMenu = await menu.count();
  out.requests = bodies.length;
  return out;
}

