  await page.route('**/api/suggestions', async (route) => {
    bodies.push(JSON.parse(route.request().postData()));
    await route.fulfill({ status: 200, headers: { 'content-type': 'text/event-stream' },
      body: `event: delta\ndata: ${JSON.stringify({ text: 'First paragraph, rewritten.' })}\n\nevent: done\ndata: {"stop_reason":"end_turn"}\n\n` });
  });
  await page.reload();
  await page.getByRole('option', { name: 'Claude Sonnet 5.5' }).waitFor({ state: 'attached' });
  const out = {};
  const palette = () => page.getByPlaceholder('Type a command or search…');
  const line = (text) => page.locator('.cm-line', { hasText: text });

  // /fix after a space: target has no trailing space
  await line('First paragraph is here.').click();
  await page.keyboard.press('End');
  await page.keyboard.type(' /fix');
  await page.locator('.cm-tooltip-autocomplete').waitFor();
  await page.keyboard.press('Enter');
  await page.getByRole('button', { name: 'Accept change 1' }).waitFor();
  const fix = bodies.at(-1);
  out.fixTarget = JSON.stringify(fix.document.slice(fix.selection.start, fix.selection.end));

  // 15. While the suggestion is under review, every AI trigger is disabled
  await page.getByRole('tab', { name: 'Editor' }).click();
  out.chipsDisabled = await page.getByRole('group', { name: 'Quick AI actions' }).getByRole('button').evaluateAll((els) => els.every((b) => b.disabled));
  out.suggestDisabled = await page.getByRole('button', { name: 'Suggest' }).isDisabled();
  await page.keyboard.press('ControlOrMeta+k');
  out.paletteAiDisabled = await page.getByRole('option', { name: /improve writing/i }).getAttribute('aria-disabled');
  await page.keyboard.press('Escape');
  await page.getByRole('tab', { name: /AI Review/ }).click();
  await page.getByRole('button', { name: 'Discard' }).click();

  // 13. Theme, export, model from the palette
  await page.keyboard.press('ControlOrMeta+k');
  await palette().fill('dark');
  await page.keyboard.press('Enter');
  out.dark = await page.evaluate(() => document.documentElement.classList.contains('dark'));
  await page.keyboard.press('ControlOrMeta+k');
  await palette().fill('export');
  const downloadPromise = page.waitForEvent('download');
  await page.keyboard.press('Enter');
  out.downloadName = (await downloadPromise).suggestedFilename();
  await page.keyboard.press('ControlOrMeta+k');
  await palette().fill('haiku');
  await page.keyboard.press('Enter');
  out.model = await page.getByRole('combobox', { name: 'AI model' }).inputValue();

  // 17. Palette in dark mode, for the screenshot
  await page.getByRole('tab', { name: 'Editor' }).click();
  await page.keyboard.press('ControlOrMeta+k');
  await page.waitForTimeout(200);
  await page.screenshot({ path: '.playwright-mcp/p6-palette-dark.png' });
  await page.keyboard.press('Escape');
  return out;
}

