async (page) => {
  await page.evaluate(() => { sessionStorage.removeItem('seeded'); });
  await page.reload();
  await page.getByRole('option', { name: /Claude/ }).first().waitFor({ state: 'attached' });
  const log = [];
  const snap = async (step) => {
    const s = await page.evaluate(() => ({
      versions: JSON.parse(localStorage.getItem('ai-docs:versions') ?? '[]').map((v) => v.source),
      focus: document.activeElement?.getAttribute('aria-label') || document.activeElement?.textContent?.trim().slice(0, 30) || document.activeElement?.tagName,
    }));
    log.push(`${step}: versions=[${s.versions}] focus=${s.focus}`);
  };
  const palette = () => page.getByPlaceholder('Type a command or search…');
  const line = (text) => page.locator('.cm-line', { hasText: text });
  await snap('fresh');

  // Start a suggestion with a pending hunk via a preset from the palette
  await line('First paragraph is here.').click();
  await page.keyboard.press('ControlOrMeta+k');
  await palette().fill('concise');
  await page.keyboard.press('Enter');
  await page.getByRole('button', { name: 'Accept change 1' }).waitFor();
  await snap('suggestion pending');

  // Open and close the palette with Escape while the suggestion is pending
  await page.keyboard.press('ControlOrMeta+k');
  await palette().waitFor();
  await page.keyboard.press('Escape');
  await palette().waitFor({ state: 'detached' });
  await snap('palette escaped');

  // Run a non-AI palette command with Enter while pending
  await page.keyboard.press('ControlOrMeta+k');
  await palette().fill('export');
  const dl = page.waitForEvent('download', { timeout: 5000 }).then((d) => d.suggestedFilename()).catch(() => 'no download');
  await page.keyboard.press('Enter');
  log.push('download: ' + (await dl));
  await snap('export via Enter');

  // Header export button while pending
  await page.getByRole('button', { name: 'Export Markdown' }).click();
  await snap('header export');
  log.push('pending text: ' + (await page.getByText(/changes pending/).textContent().catch(() => 'none')));
  return log;
}

